            $vehiculo['color_vehiculo_id'] = ColorVehiculo::firstOrCreate(['nombre' => $vehiculo['color']])->id;
            unset($vehiculo['color']);
            $vehiculo['uso_vehiculo_id'] = UsoVehiculo::firstOrCreate(['nombre' => $vehiculo['uso']])->id;
            unset($vehiculo['uso']);
